signature: public static String substringAfter(String str, int separator)
body:     public static String substringAfter(String str, int separator) {
        if (isEmpty(str)) {
            return str;
        }
        int index = str.indexOf(separator);
        return index == INDEX_NOT_FOUND ? str : str.substring(index + 1);
    }

